import { randomInt } from 'node:crypto';
import { patientRepository } from '../repositories/patient.repository.js';
import { AppError } from '../utils/app-error.js';
export const patientService = { async list(query) { const where = { deletedAt: null, ...(query.status ? { status: query.status } : {}), ...(query.search ? { OR: [{ mrn: { contains: query.search, mode: 'insensitive' } }, { firstName: { contains: query.search, mode: 'insensitive' } }, { lastName: { contains: query.search, mode: 'insensitive' } }, { phone: { contains: query.search } }] } : {}) }; const [data, total] = await Promise.all([patientRepository.list(where, (query.page - 1) * query.page_size, query.page_size, { [query.sort_by]: query.sort_order }), patientRepository.count(where)]); return { data, pagination: { page: query.page, page_size: query.page_size, total, total_pages: Math.ceil(total / query.page_size) } }; }, async details(id) { const item = await patientRepository.find(id); if (!item)
        throw new AppError(404, 'Patient was not found.', 'PATIENT_NOT_FOUND'); return item; }, async create(input) { const mrn = `MRN-${new Date().getUTCFullYear()}-${Date.now().toString().slice(-6)}${randomInt(10, 99)}`; return patientRepository.create({ ...input, mrn, email: input.email || null, middleName: input.middleName || null, city: input.city || null, emergencyContact: input.emergencyContact || null, allergies: input.allergies ?? [] }); }, async update(id, input) { await this.details(id); return patientRepository.update(id, input); }, async archive(id) { await this.details(id); return patientRepository.update(id, { status: 'Inactive', deletedAt: new Date() }); } };
